import styles from "./Banner.module.css";
import { Icon } from "./Icon.jsx";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

export function Banner({ variant = "neutral", title, icon, image, action, onClose, closeLabel = "Close", children, className, testId }) {
    return (
        <div className={cx(styles.banner, styles[variant], className)} role="region" aria-label={title} data-testid={testId}>
            {image ? <div className={styles.media}>{image}</div> : icon ? <Icon name={icon} size="large" className={styles.icon} /> : null}
            <div className={styles.content}>
                {title ? <div className={styles.title}>{title}</div> : null}
                <div className={styles.body}>{children}</div>
                {action ? <div className={styles.action}>{action}</div> : null}
            </div>
            {onClose ? <IconButton icon="close" label={closeLabel} size="small" className={styles.close} onClick={onClose} /> : null}
        </div>
    );
}
